// Read-only view of the method registry. registry/index.json is generated by
// `npm run registry:check` (see registry/README.md); importing it bundles it, so no fs at runtime.
import index from "../../registry/index.json";

export type Health = "untested" | "working" | "degraded" | "broken";
export type Soundness = "unreviewed" | "reviewed" | "audited" | "revoked";

export type VersionStatus = {
  version: string;
  sha256: string;
  health: Health;
  soundness: Soundness;
  last_checked?: string;
  health_note?: string;
  reviewed_by?: string[];
  audit?: string;
  revoked?: { reason: string; date: string; advisory?: string };
  deprecated?: { superseded_by: string; reason?: string };
};

export type Manifest = {
  id: string;
  version: string;
  proof_type: string;
  runtime: string[];
  claim: string;
  risk?: "low" | "medium" | "high";
  disclose: { mode: string; output: string; comparison?: string; value?: unknown };
  nullifier?: { scope: string; derived_from: string };
  privacy?: { summary?: string; guarantees: string[]; limits: string[]; trust?: string[] };
  badge: { label: string; icon: string; color: string };
  freshness: { max_age_days: number; stale_after_days: number };
  maintainers: string[];
  source?: { name: string; url?: string; path?: string };
  changelog?: string;
  tags?: string[];
  config: Record<string, unknown>;
};

export type Method = { id: string; latest: string; versions: VersionStatus[]; manifest: Manifest };

export type ProofType = {
  id: string;
  name: string;
  description: string;
  status: "available" | "experimental" | "planned";
  runtimes: string[];
};

const registry = index as unknown as { proof_types: ProofType[]; methods: Method[] };

export const REPO = "https://github.com/leonmak/zeroknowledger";

export const proofTypes = registry.proof_types;
export const methods = registry.methods;

export const getMethod = (id: string) => methods.find((m) => m.id === id);
export const getProofType = (id: string) => proofTypes.find((t) => t.id === id);

/** The version to use for new proofs: newest that isn't revoked or deprecated. */
export const recommended = (m: Method) =>
  [...m.versions].reverse().find((v) => v.soundness !== "revoked" && !v.deprecated);

export const HEALTH_COLOR: Record<Health, string> = {
  working: "#7ee787",
  degraded: "#d29922",
  broken: "#f85149",
  untested: "#8b949e",
};

export const SOUNDNESS_COLOR: Record<Soundness, string> = {
  audited: "#7ee787",
  reviewed: "#58a6ff",
  unreviewed: "#8b949e",
  revoked: "#f85149",
};
